# simpler: find shifts where overlapping nonzero cells agree
def best_shift(a,b):
    res=[]
    for s in range(-14,15):
        ok=[];bad=[]
        for c in range(28):
            if 0<=c+s<28 and (a[c] or b[c+s]):
                if a[c]==b[c+s]: ok.append(c)
                else: bad.append(c)
        if bad==[] and len(ok)>5: res.append((s,len(ok)))
    return res
